        const summary = screen.getByText('tokens: 0')
        fireEvent.mouseOver(summary)

        const tooltip = await screen.findByText('total: 0, input: 0, cached input: 0, output: 0, reasoning: 0')
        expect(tooltip).not.toHaveTextContent('$')
    })
})
