import { Box } from '@mui/material'

const UNIT_SUFFIXES: { divisor: number, suffix: string }[] = [
    { divisor: 1_000_000_000, suffix: 'B' },
    { divisor: 1_000_000, suffix: 'M' },
    { divisor: 1_000, suffix: 'K' },
]

interface TokenCountProps {
    value: number
}

/**
 * Abbreviates a token count for at-a-glance reading: `1234` becomes `1.2K`, `2000000` becomes `2M`.
 * Values below 1000 keep their exact integer form. Rounding to one decimal can push the mantissa to
 * 1000 (`999950` rounds to `1000.0K`), so a mantissa that reaches the next threshold promotes to the
 * larger suffix instead. The locale is the user default, so only the decimal separator varies.
 */
export function formatTokenCount(value: number): string {
    const magnitude = Math.abs(value)
    for (const { divisor, suffix } of UNIT_SUFFIXES) {
        if (magnitude < divisor) continue
        const mantissa = value / divisor
        const rounded = Math.abs(Number(mantissa.toFixed(1)))
        // The carry case: rounding reached the next magnitude, so let the larger suffix format it.
        if (rounded >= 1_000 && divisor !== UNIT_SUFFIXES[0].divisor) continue

        return `${new Intl.NumberFormat(undefined, { maximumFractionDigits: 1 }).format(mantissa)}${suffix}`
    }

    return new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(value)
}

/** Inline abbreviated token count. Carries no tooltip; consuming surfaces own their own. */
export function TokenCount({ value }: TokenCountProps) {
    return <Box component="span">{formatTokenCount(value)}</Box>
}
